features.sample:
let car: Vehicle = build_vehicle()

let view: borrow Vehicle = borrow car   // exclusive borrow begins
print(view.engine.rpm)                  // last use of `view`
                                        // borrow ends HERE, not at block end

transfer_ownership(transfer car)        // OK: `view` is already dead

// NOT sendable: a bare mutable share interior would race
let bad: share Counter = share Counter(value = 0)

// sendable: the Mutex bundle re-establishes exclusivity at run time
let good: share Mutex<Counter> = share new_mutex(Counter(value = 0))

def triage(email: tainted String) -> tainted Result<Action, Error>:
    let p = prompt(
        instruction = "Classify the message as spam, urgent, or routine.",
        data        = [email])        // data part: tainted welcome
    let reply = Model.complete(prompt = p)?  // model output: born tainted
    action_of(label = reply.text)

def hijacked(email: tainted String) -> Prompt:
    prompt(instruction = email, data = [])   // COMPILE ERROR

trust def raw(n: Int) -> Int
    requires "n is a valid slot index"

def good(n: Int) -> Int:
    trust "n was range-checked by the caller": raw(n = n)

def bad(n: Int) -> Int:
    raw(n = n)      // AX0801: call to trust def outside a trust block

let dloss        = grad(loss)                 // dloss : same shape as w
let hessian_diag = grad(grad(loss))
let batched_loss = vmap(f = example_loss, over = {x: batch, y: batch})

schedule blur as tiled_fused:
    @tile(y, x, by = (32, 32))
    @fuse(by, blur)
    @vectorize(x, width = 8)
    @parallel(y)
